from pathlib import Path
import sys,subprocess,shutil
ROOT=Path.cwd().resolve();base=Path(sys.argv[1]).resolve();D=base/'strap-density-study/shell';common=ROOT/'strap-density-study/shell'
s=(D/'build_ordered.py').read_text().replace('ordered-v9','uv-v10');s=s.replace('tris=[];mats=[];boundary=[]','tris=[];mats=[];boundary=[];params=[];kinds=[];kind=0').replace('def add(a,b,c,mat):','def add(a,b,c,mat,ss=None):').replace('tris.append(t);mats.append(int(mat))','tris.append(t);mats.append(int(mat));params.append([np.nan]*3 if ss is None else ss);kinds.append(kind)').replace('material((sa[i]+sa[i+1]+sb[j])/3))','material((sa[i]+sa[i+1]+sb[j])/3),[sa[i],sa[i+1],sb[j]])').replace('material((sa[i]+sb[j]+sb[j+1])/3))','material((sa[i]+sb[j]+sb[j+1])/3),[sa[i],sb[j+1],sb[j]])').replace('# Round edge:','kind=1\n# Round edge:').replace('# Bore wall','kind=2\n# Bore wall').replace('base=cur.copy();','kind=1\nbase=cur.copy();').replace('# Constrained cap core','kind=3\n# Constrained cap core').replace('triangles=T,materials=M','triangles=T,materials=M,profileS=np.array(params),kind=np.array(kinds)');assert 'profileS=np.array(params)'in s;(D/'build_uv.py').write_text(s)
s=(D/'stitch_ordered.py').read_text().replace('ordered-v9','uv-v10').replace("t,ids=split(q['triangles']);np.savez_compressed(O/'stitched-new.npz',triangles=t,materials=q['materials'][ids])","t,ids=split(np.concatenate([q['triangles'],q['profileS'][:,:,None]],2));np.savez_compressed(O/'stitched-new.npz',triangles=t[:,:,:3],profileS=t[:,:,3],kind=q['kind'][ids],materials=q['materials'][ids])");assert 'profileS=t[:,:,3]'in s;(D/'stitch_uv.py').write_text(s)
s=(D/'attributes_ordered.py').read_text().replace('ordered-v9','uv-v10').replace("T=q['triangles'];M=q['materials'];","T=q['triangles'];M=q['materials'];PS=q['profileS'];K=q['kind'];").replace("T=np.array([t[[0,2,1]]if flip[i]else t for i,t in enumerate(T)])","T=np.array([t[[0,2,1]]if flip[i]else t for i,t in enumerate(T)]);PS=np.array([p[[0,2,1]]if flip[i]else p for i,p in enumerate(PS)])").replace('outputs=[];errors=[]','from chart_uv import map_uv\noutputs=[];errors=[]').replace('new=np.concatenate([t,n,uv],2);','new=map_uv(np.concatenate([t,n,uv],2),PS[mask],K[mask],mi);')
old="np.savez_compressed(O/f'new-patch-{mi}.npz',triangles=new.astype('<f4'));";new="np.savez_compressed(O/f'new-patch-{mi}.npz',triangles=new.astype('<f4'),profileS=PS[mask],kind=K[mask]);"
if old in s:s=s.replace(old,new)
else:s=s.replace("old=np.load(O/f'outside-{mi}.npz')",new+"old=np.load(O/f'outside-{mi}.npz')")
assert 'profileS=PS[mask]'in s;(D/'attributes_uv.py').write_text(s)
for name in ['chart_uv.py','refine_uv.py']:shutil.copyfile(common/name,D/name)
for name in ['build_uv.py','stitch_uv.py','attributes_uv.py','refine_uv.py']:subprocess.run([sys.executable,str(D/name)],cwd=base,check=True)
